const express = require('express');
const { authenticator } = require('otplib');
const { TenantMemberDb, TenantAdminRegistry } = require('../models/tenants');

const app = express();
app.use(express.json());

app.post('/api/tenants/:tenantId/members/:memberId/reset-2fa', async (req, res) => {
  if (!req.user || !req.user.id || !req.user.mfaSecret) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { adminOtpCode } = req.body;
  const { tenantId, memberId } = req.params;

  // Confirm caller is a verified administrator of the specified tenant
  const isAdmin = await TenantAdminRegistry.isAdminOfTenant(req.user.id, tenantId);
  if (!isAdmin) {
    return res.status(403).json({ error: 'Access denied: not an administrator of this tenant' });
  }

  const isCodeValid = authenticator.check(adminOtpCode, req.user.mfaSecret);
  if (!isCodeValid) {
    return res.status(401).json({ error: 'Invalid admin authentication code' });
  }

  // Ensure targeted member belongs to the same tenant
  const member = await TenantMemberDb.findOne({
    where: {
      id: memberId,
      tenantId: tenantId
    }
  });

  if (!member) {
    return res.status(404).json({ error: 'Member not found in specified tenant' });
  }

  member.twoFactorEnabled = false;
  member.twoFactorSecret = null;
  await member.save();

  res.json({ success: true, message: 'Member 2FA reset successfully', memberId });
});

app.listen(6008);
